// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.Random;

import org.junit.jupiter.api.Test;

class LmdbNativeChangeDetectorTest {

	private static final LmdbNativePosteriorConfig CONFIG = LmdbNativePosteriorConfig.defaults();

	private static LmdbNativeCostPosteriorStore.FamilyKey familyKey(String family) {
		return new LmdbNativeCostPosteriorStore.FamilyKey(LmdbNativeRegimeKey.STEADY,
				LmdbNativeCostPosteriorStore.Lane.DIRECT,
				new LmdbNativeFamilyShapeKey(family, LmdbNativePhysicalVariantKey.ExecutionMode.INTERPRETED, 0));
	}

	@Test
	void stationaryResidualsNeverTrip() {
		LmdbNativeChangeDetector detector = new LmdbNativeChangeDetector(CONFIG);
		LmdbNativeCostPosteriorStore.FamilyKey key = familyKey("nestedLoop");
		Random random = new Random(42);
		for (int i = 0; i < 100_000; i++) {
			double residual = LmdbNativeGaussianMath.huberClip(random.nextGaussian(), CONFIG.huberSigmas());
			assertFalse(detector.offer(key, residual), "stationary stream tripped at observation " + i);
		}
	}

	@Test
	void aSustainedShiftTripsWithinTensOfObservations() {
		LmdbNativeChangeDetector detector = new LmdbNativeChangeDetector(CONFIG);
		LmdbNativeCostPosteriorStore.FamilyKey key = familyKey("hashJoin");
		Random random = new Random(7);
		for (int i = 0; i < 200; i++) {
			detector.offer(key, LmdbNativeGaussianMath.huberClip(random.nextGaussian(), CONFIG.huberSigmas()));
		}
		int trippedAt = -1;
		for (int i = 0; i < 200; i++) {
			double shifted = LmdbNativeGaussianMath.huberClip(1.5 + random.nextGaussian(), CONFIG.huberSigmas());
			if (detector.offer(key, shifted)) {
				trippedAt = i;
				break;
			}
		}
		assertTrue(trippedAt >= 0, "a +1.5 sigma shift must trip");
		assertTrue(trippedAt < 60, "trip should arrive within tens of observations, took " + trippedAt);
	}

	@Test
	void aTripResetsTheStateAndKeysAreIndependent() {
		LmdbNativeChangeDetector detector = new LmdbNativeChangeDetector(CONFIG);
		LmdbNativeCostPosteriorStore.FamilyKey drifting = familyKey("drifting");
		LmdbNativeCostPosteriorStore.FamilyKey steady = familyKey("steady");
		int trips = 0;
		for (int i = 0; i < 100; i++) {
			if (detector.offer(drifting, 3.0)) {
				trips++;
			}
			assertFalse(detector.offer(steady, 0.0), "the steady key must be unaffected");
		}
		// with delta 0.25 and lambda 25, a constant +3 residual advances 2.75/observation: first trip at
		// observation 10, then the reset state re-accumulates and trips every 10 thereafter
		assertTrue(trips >= 5, "resets must allow repeated trips, saw " + trips);
		assertEquals(1, detector.trackedKeys(), "the tripped key's state is removed; the steady key remains");
	}
}
